if (!root) return;
if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    if (!root->left || !root->right) {
        TreeNode* temp = root->left ? root->left : root->right;
        delete root;
        root = temp;
    } else {
        TreeNode* succ = root->right;
        while (succ->left) succ = succ->left;
        root->data = succ->data;
        avlDelete(root->right, succ->data);
    }
}
if (!root) return;
root->height = 1 + std::max(root->left ? root->left->height : 0,
                            root->right ? root->right->height : 0);
int balance = (root->left ? root->left->height : 0) -
              (root->right ? root->right->height : 0);
if (balance > 1) {
    int leftBal = (root->left->left ? root->left->left->height : 0) -
                  (root->left->right ? root->left->right->height : 0);
    if (leftBal >= 0) {
        avlRotateRight(root);
    } else {
        avlRotateLeft(root->left);
        avlRotateRight(root);
    }
} else if (balance < -1) {
    int rightBal = (root->right->right ? root->right->right->height : 0) -
                  (root->right->left ? root->right->left->height : 0);
    if (rightBal >= 0) {
        avlRotateLeft(root);
    } else {
        avlRotateRight(root->right);
        avlRotateLeft(root);
    }
}

